   121  void
   122  xmlFuzzCheckMallocFailure(const char *func, int expect) {
   123      if (fuzzAllocFailed != expect) {
   124          fprintf(stderr, "%s: malloc failure %s reported\n",
   125                  func, fuzzAllocFailed ? "not" : "erroneously");
   126          abort();
   127      }
   128  }
