   135  void
   136  xmlFuzzDataInit(const char *data, size_t size) {
   137      fuzzData.data = data;
   138      fuzzData.size = size;
   139      fuzzData.ptr = data;
   140      fuzzData.remaining = size;
   141
   142      fuzzData.outBuf = xmlMalloc(size + 1);
   143      fuzzData.outPtr = fuzzData.outBuf;
   144
   145      fuzzData.entities = xmlHashCreate(8);
   146      fuzzData.mainUrl = NULL;
   147      fuzzData.mainEntity = NULL;
   148  }
